// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public { c = new C(address(new Log())); atk = new Attacker(c); }

    function testFuzz_property(uint256 deposit, uint256 amount, uint256 extra) public {
        deposit = bound(deposit, 2 ether, 100 ether);
        amount = bound(amount, 1, deposit);
        extra = bound(extra, 1 wei, 10 ether);

        vm.deal(address(atk), deposit + extra);
        atk.put(deposit);            // sets unlockTime = now, balance = deposit
        vm.warp(block.timestamp + 1); // time past unlockTime
        uint256 before = c.Acc(address(atk)).balance;

        atk.collect(amount, extra);   // during payout, attacker re-enters Put with `extra`

        uint256 afterB = c.Acc(address(atk)).balance;
        assertTrue(afterB == before - amount);
    }
}

contract Attacker {
    C c;
    uint256 extra;
    bool reentered;

    constructor(C _c) { c = _c; }

    function put(uint256 amt) external payable {
        c.Put{value: amt}(0);
    }

    function collect(uint256 amt, uint256 ex) external {
        extra = ex;
        reentered = false;
        c.Collect(amt);
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            c.Put{value: extra}(0);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 am, uint256 extra, uint256 warpTo) public {
        uint256 minSum = c.MinSum();
        bound(am, minSum, 1000 ether);
        bound(extra, 1, 100 ether);
        bound(warpTo, block.timestamp + 1, block.timestamp + 365 days);

        Attacker a = new Attacker(c);
        vm.deal(address(a), am + extra);

        // Initial deposit via Put, from the attacker
        a.doPut(am);

        // Let the unlock time pass so Collect succeeds
        vm.warp(warpTo);

        // Collect pays out to the attacker; the attacker's receive() re-enters Put
        // with the remaining `extra` ether.
        a.doCollect(am);

        // General rule: a completed Collect drains the account exactly;
        // no re-entrant Put during the payout may augment the balance.
        assertTrue(c.Acc(address(a)).balance == 0);
    }
}

contract Attacker {
    C c;
    constructor(C c_) { c = c_; }
    function doPut(uint256 amt) external payable {
        c.Put{value: amt}(0);
    }
    function doCollect(uint256 amt) external {
        c.Collect(amt);
    }
    receive() external payable {
        c.Put{value: msg.value}(0);
    }
}

