pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;

    function setUp() public { c = new C(address(new Log())); atk = new Attacker(c); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 1000 ether);
        vm.deal(address(atk), amount);
        vm.prank(address(atk));
        c.Put(0);
        vm.warp(block.timestamp + 2);
        // full-amount Collect; during the payout the attacker re-enters Put
        atk.attack(amount);
        // General rule: exactly two History entries exist (deposit log + collect log);
        // index 2 must be absent. In the lockless mutant the re-entrant Put logged a third entry.
        bool thirdEntryAbsent;
        try c.History(2) returns (address, string memory, uint256, uint256) {
            thirdEntryAbsent = false;
        } catch {
            thirdEntryAbsent = true;
        }
        assertTrue(thirdEntryAbsent);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    function attack(uint256 am) external {
        c.Collect(am);
    }
    receive() external payable {
        try c.Put{value: msg.value / 2}(0) {} catch {}
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 futureTime) public {
        vm.warp(1);
        amount = bound(amount, 1 ether, 1000 ether);
        futureTime = bound(futureTime, 2, type(uint256).max);

        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.attack(amount, futureTime);

        // General rule: a completed Collect may never leave the account with a
        // future unlockTime, because a re-entrant Put during the payout must be
        // blocked by the reentrancy lock.
        (uint256 unlockTime, ) = c.Acc(address(a));
        assertTrue(unlockTime <= block.timestamp);
    }
}

contract Attacker {
    C c;
    uint256 fut;

    constructor(C _c) { c = _c; }

    function attack(uint256 am, uint256 f) external {
        fut = f;
        c.Put{value: am}(0);        // fund the account, unlockTime = now
        c.Collect(am);              // full withdrawal; payout re-enters receive()
    }

    receive() external payable {
        // re-entrant deposit with a far-future unlock time; ignore revert
        // (reference C reverts it via the lock, mutant accepts it)
        (bool s, ) = address(c).call(abi.encodeWithSelector(c.Put.selector, fut));
        s;
    }
}
